[
  {
    "title": "half-point-baseline",
    "claim": "In Image #8, the denominator of the result’s '2½' drops onto a separate line below '0 — 2', and the HUD fraction also extends below its adjacent whole number.",
    "reason": "The total looks like disconnected numbers rather than one score.",
    "suggest": "Render each score as a non-wrapping inline group with a compact fraction vertically centered beside the whole number."
  },
  {
    "title": "impact-contact-offset",
    "claim": "In Image #12, bright impact streaks appear around Asmongold’s belt while HasanAbi’s extended foot meets his shoulder or neck, roughly 50 CSS pixels higher.",
    "reason": "The effect and attacking foot disagree about where contact occurs.",
    "suggest": "Anchor the concentrated impact burst to the attacking limb’s visible contact point instead of the defender’s torso center."
  },
  {
    "title": "indistinct-kicking-foot",
    "claim": "In Image #13, I cannot distinguish a foot beyond the raised trouser cuff, although the supporting foot is clearly visible.",
    "reason": "The kick’s striking endpoint and reach are difficult to read.",
    "suggest": "Revise that kick pose so the ankle and foot have a complete, clearly separated silhouette, preserving its existing ground anchor."
  },
  {
    "title": "undersized-fighter-names",
    "claim": "In Image #3, the HUD fighter names have approximately 10 CSS pixels of visible capital-letter height at the stated 390-pixel viewport width.",
    "reason": "Players must read tiny, widely spaced lettering to associate each score with its fighter.",
    "suggest": "Use at least 18px computed text for fighter names, reduce letter spacing, and place each name above its score if necessary."
  },
  {
    "title": "desktop-bindings-not-shown",
    "claim": "Image #9 shows pads labeled 'STANCE' and 'TECHNIQUE' but no visible keyboard bindings for either control.",
    "reason": "A desktop player cannot determine the keyboard controls from this screen.",
    "suggest": "Display the actual mapped keyboard keys beside each pad’s directions on desktop, while retaining the touch layout on phones."
  }
]
